<script>
	import { onMount } from 'svelte';
	import { createBrowserClient } from '@supabase/ssr';
	import { env } from '$env/dynamic/public';
	import { Sprout, House, Wheat, CalendarDays, MessageCircle, BookOpen, UserRound, Bell, Search, Menu, X, ChevronRight, MapPin, CloudSun, Droplets, Plus, ArrowUpRight, Check, Clock3, Leaf, AlertTriangle, Send, ImagePlus, CloudUpload, LogOut, Settings, ShieldCheck, Users, ChevronDown, ArrowLeft, Sun, Bug, FileText, Eye, CircleHelp, MoreHorizontal, CalendarClock, Tractor, Activity } from '@lucide/svelte';
	export let data;
	const configured = Boolean(data.supabaseConfigured && env.PUBLIC_SUPABASE_URL && env.PUBLIC_SUPABASE_PUBLISHABLE_KEY);
	let supabase = configured ? createBrowserClient(env.PUBLIC_SUPABASE_URL, env.PUBLIC_SUPABASE_PUBLISHABLE_KEY) : null;
	let current = 'Beranda', role = 'Petani', user = data.user, loggedIn = Boolean(data.user), menuOpen = false, modal = '', toast = '', toastTimer;
	let profile = { name: data.user?.user_metadata?.full_name || data.user?.email?.split('@')[0] || 'Budi Santoso', location: 'Cibinong, Bogor', email: data.user?.email || 'budi@example.com', role: 'petani', requestedRole: 'farmer' };
	let fields = [
		{id:'sample-corn', name:'Kebun Utama', crop:'Jagung Manis', area:1000, location:'Cibinong, Bogor', planted:'2026-09-01', harvest:'2026-11-25', status:'Tumbuh dengan baik', stage:'Fase vegetatif', progress:32, image:'https://images.unsplash.com/photo-1551754655-cd27e38d2076?auto=format&fit=crop&w=900&q=85'},
		{id:'sample-chili', name:'Kebun Cabai', crop:'Cabai Merah', area:500, location:'Cibinong, Bogor', planted:'2026-09-10', harvest:'2027-01-08', status:'Perlu pemantauan', stage:'Pertumbuhan awal', progress:18, image:'https://images.unsplash.com/photo-1588252303782-cb80119abd6d?auto=format&fit=crop&w=900&q=85'}
	];
	let activities = [
		{id:'a1',title:'Penyiraman pagi',kind:'Penyiraman',date:new Date().toISOString().slice(0,10),time:'07:00',field:'Kebun Utama',done:true},
		{id:'a2',title:'Cek kondisi daun',kind:'Pemantauan',date:new Date().toISOString().slice(0,10),time:'15:30',field:'Kebun Utama',done:false},
		{id:'a3',title:'Pemupukan susulan',kind:'Pemupukan',date:'2026-09-30',time:'08:00',field:'Kebun Utama',done:false},
		{id:'a4',title:'Periksa bagian bawah daun',kind:'Pengendalian hama',date:'2026-10-02',time:'07:30',field:'Kebun Cabai',done:false}
	];
	let consultations = [{id:'c1',name:'Siti Rahmawati, S.P.',specialty:'Tanaman Pangan',last:'Daun jagung mulai menguning',time:'08.15',online:true}];
	let messages = [{from:'officer',text:'Selamat pagi, Pak Budi. Bisa ceritakan sejak kapan daun mulai terlihat kuning?',time:'08.15'},{from:'me',text:'Mulai kemarin, Pak. Terutama daun bagian bawah.',time:'08.18'},{from:'officer',text:'Baik, saya bantu cek ya. Apakah tanah di sekitar tanaman cukup lembap? Boleh kirim foto tanamannya.',time:'08.20'}];
	let articles = [{title:'Mengenali jagung yang kekurangan air',category:'Budidaya Jagung',read:'4 menit',image:'https://images.unsplash.com/photo-1560493676-04071c5f467b?auto=format&fit=crop&w=900&q=85',text:'Tanaman jagung yang kekurangan air biasanya menunjukkan daun menggulung, tampak layu pada siang hari, dan pertumbuhannya melambat. Periksa kelembapan tanah sebelum menambah penyiraman.'},{title:'Cara mengamati hama ulat grayak lebih awal',category:'Hama & Penyakit',read:'6 menit',image:'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=900&q=85',text:'Amati permukaan bawah daun secara rutin. Lubang kecil dan kotoran di pucuk bisa menjadi tanda awal serangan. Catat bagian tanaman yang terdampak dan diskusikan dengan penyuluh.'},{title:'Menyusun jadwal tanam yang lebih teratur',category:'Perencanaan',read:'5 menit',image:'https://images.unsplash.com/photo-1464226184884-fa280b87c399?auto=format&fit=crop&w=900&q=85',text:'Jadwal yang sederhana dapat membantu kegiatan budidaya berjalan lebih teratur. Catat tanggal tanam, penyiraman, pemupukan, dan pengamatan tanaman.'}];
	let pests = [{name:'Ulat grayak',crop:'Jagung',level:'Waspada',risk:'Sedang',desc:'Periksa pucuk dan bagian bawah daun, terutama setelah hujan.',color:'amber'},{name:'Hawar daun',crop:'Jagung',level:'Pantau',risk:'Rendah',desc:'Amati bercak memanjang pada daun. Jaga jarak tanam dan sirkulasi udara.',color:'green'},{name:'Antraknosa',crop:'Cabai',level:'Pantau',risk:'Rendah',desc:'Perhatikan bercak cekung pada buah cabai dan hindari daun terlalu lembap.',color:'green'}];
	let notifications = [{title:'Jadwal penyiraman',body:'Waktunya menyiram Kebun Utama pagi ini.',time:'07.00',unread:true},{title:'Pesan dari Siti Rahmawati',body:'Penyuluh membalas konsultasi Anda.',time:'08.20',unread:true},{title:'Cuaca Bogor',body:'Kemungkinan hujan ringan menjelang sore.',time:'Kemarin',unread:false}];
	let selectedField = null, selectedArticle, selectedOfficer, selectedConsultation, consultText = '', consultTopic = 'Masalah tanaman', searchText = '', chatText = '', loginEmail = '', loginRole = 'petani', activityForm = {title:'',kind:'Penyiraman',date:new Date().toISOString().slice(0,10),time:'07:00',field:''}, fieldForm = {name:'',crop:'Jagung Manis',area:'',location:'Cibinong, Bogor',planted:new Date().toISOString().slice(0,10)}, uploadFile = null;
	const nav = [{name:'Beranda',icon:House},{name:'Lahan Saya',icon:Wheat},{name:'Kalender Tani',icon:CalendarDays},{name:'Temu Penyuluh',icon:MessageCircle},{name:'Belajar Tani',icon:BookOpen},{name:'Hama & Penyakit',icon:Bug}];
	const officerNav = [{name:'Dashboard Penyuluh',icon:House},{name:'Permintaan Konsultasi',icon:MessageCircle},{name:'Petani Binaan',icon:Users},{name:'Jadwal Kunjungan',icon:CalendarDays},{name:'Materi Edukasi',icon:BookOpen}];
	const adminNav = [{name:'Dashboard Admin',icon:House},{name:'Data Pengguna',icon:Users},{name:'Verifikasi Penyuluh',icon:ShieldCheck},{name:'Kelola Artikel',icon:BookOpen},{name:'Laporan & Hama',icon:FileText}];
	function notify(text){toast=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast='',3000)}
	function go(name){current=name;menuOpen=false;if(name==='Beranda'&&selectedField)selectedField=null;}
	function goLanding(){current='Beranda';loggedIn=false;user=null;}
	function setDemo(nextRole='Petani'){role=nextRole;loggedIn=true;user=null;profile={...profile,name:nextRole==='Penyuluh'?'Siti Rahmawati':'Budi Santoso',role:nextRole.toLowerCase()};current=nextRole==='Penyuluh'?'Dashboard Penyuluh':nextRole==='Admin'?'Dashboard Admin':'Beranda';modal='';notify(`Mode demo ${nextRole} aktif`)}
	async function signInGoogle(){
		if(!supabase){notify('Hubungkan Supabase terlebih dahulu. Mode demo tetap bisa digunakan.');return}
		localStorage.setItem('temu-role',loginRole);
		const {error}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:`${location.origin}/auth/callback?next=/`}});
		if(error)notify(`Login Google gagal: ${error.message}`);
	}
	async function signInEmail(){if(!supabase){notify('Tambahkan konfigurasi Supabase untuk mengirim tautan masuk.');return}if(!loginEmail){notify('Masukkan alamat email terlebih dahulu.');return}const {error}=await supabase.auth.signInWithOtp({email:loginEmail,options:{emailRedirectTo:`${location.origin}/auth/callback?next=/`}});if(error)notify(error.message);else notify('Tautan masuk telah dikirim ke email Anda.')}
	async function signOut(){if(supabase)await supabase.auth.signOut();loggedIn=false;user=null;current='Beranda';notify('Anda sudah keluar.')}
	async function syncRemote(){if(!supabase||!user)return;const {data:p}=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();if(p){profile={...profile,name:p.display_name||profile.name,location:p.region||profile.location,role:p.role,requestedRole:p.requested_role};role=p.role==='officer'?'Penyuluh':p.role==='admin'?'Admin':'Petani';if(role==='Penyuluh')current='Dashboard Penyuluh';if(role==='Admin')current='Dashboard Admin'}
		const {data:f,error:fe}=await supabase.from('fields').select('*').order('created_at',{ascending:false});if(!fe&&f?.length)fields=await Promise.all(f.map(async x=>{let image=fields[0]?.image;if(x.image_path){const {data:signed}=await supabase.storage.from('field-photos').createSignedUrl(x.image_path,3600);image=signed?.signedUrl||image}return {...x,name:x.name,crop:x.crop,area:x.area_m2,location:x.location,planted:x.planted_at,harvest:x.estimated_harvest,status:x.status||'Tumbuh dengan baik',stage:x.growth_stage||'Fase vegetatif',progress:x.progress||28,image}}));
		const {data:a}=await supabase.from('activities').select('*').order('scheduled_at');if(a?.length)activities=a.map(x=>({...x,title:x.title,kind:x.kind,date:x.scheduled_at?.slice(0,10),time:x.scheduled_at?.slice(11,16),field:x.field_name||'Lahan',done:x.completed}));
		const {data:c}=await supabase.from('consultations').select('id,status,created_at,profiles!consultations_officer_id_fkey(display_name,specialty)').order('created_at',{ascending:false});if(c?.length)consultations=c.map(x=>({id:x.id,name:x.profiles?.display_name||'Penyuluh',specialty:x.profiles?.specialty||'Pertanian',last:'Konsultasi baru',time:new Date(x.created_at).toLocaleDateString('id-ID'),online:x.status==='active'}));
		const {data:ar}=await supabase.from('articles').select('*').eq('published',true);if(ar?.length)articles=ar.map(x=>({title:x.title,category:x.category,read:`${x.read_minutes||4} menit`,image:x.cover_url||articles[0].image,text:x.body}));
	}
	onMount(()=>{if(supabase){if(user)syncRemote();const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{if(session?.user){user=session.user;loggedIn=true;profile.name=session.user.user_metadata?.full_name||session.user.email?.split('@')[0]||'Petani';profile.email=session.user.email;const wanted=localStorage.getItem('temu-role');if(wanted==='penyuluh'){supabase.from('profiles').update({requested_role:'officer'}).eq('id',session.user.id).then(()=>syncRemote()).finally(()=>localStorage.removeItem('temu-role'));}else syncRemote();}else{user=null;loggedIn=false}});return()=>subscription.unsubscribe()}});
	function openAddField(){fieldForm={name:'',crop:'Jagung Manis',area:'',location:profile.location,planted:new Date().toISOString().slice(0,10)};uploadFile=null;modal='field'}
	async function saveField(){if(!fieldForm.name||!fieldForm.area){notify('Nama lahan dan luas lahan perlu diisi.');return}let image=fields[0]?.image;if(supabase&&user){let imagePath=null;if(uploadFile){if(!uploadFile.type.startsWith('image/')||uploadFile.size>5*1024*1024){notify('Gunakan foto maksimal 5 MB.');return}imagePath=`${user.id}/${crypto.randomUUID()}-${uploadFile.name.replace(/[^a-zA-Z0-9.-]/g,'_')}`;const {error:up}=await supabase.storage.from('field-photos').upload(imagePath,uploadFile,{contentType:uploadFile.type,upsert:false});if(up){notify(`Foto belum tersimpan: ${up.message}`);return}}
		const {data:row,error}=await supabase.from('fields').insert({owner_id:user.id,name:fieldForm.name,crop:fieldForm.crop,area_m2:Number(fieldForm.area),location:fieldForm.location,planted_at:fieldForm.planted,image_path:imagePath}).select().single();if(error){notify(`Lahan gagal disimpan: ${error.message}`);return}fields=[{...row,id:row.id,area:row.area_m2,planted:row.planted_at,harvest:row.estimated_harvest||'—',status:'Baru ditambahkan',stage:'Baru ditanam',progress:5,image},...fields];}
		else fields=[{id:crypto.randomUUID(),...fieldForm,area:Number(fieldForm.area),harvest:'—',status:'Baru ditambahkan',stage:'Baru ditanam',progress:5,image},...fields];modal='';notify('Lahan berhasil ditambahkan.')}
	function openAddActivity(){activityForm={title:'',kind:'Penyiraman',date:new Date().toISOString().slice(0,10),time:'07:00',field:fields[0]?.name||''};modal='activity'}
	async function saveActivity(){if(!activityForm.title){notify('Nama kegiatan perlu diisi.');return}const scheduled_at=`${activityForm.date}T${activityForm.time}:00`;if(supabase&&user){const {data:row,error}=await supabase.from('activities').insert({owner_id:user.id,field_id:fields.find(x=>x.name===activityForm.field)?.id||null,field_name:activityForm.field,title:activityForm.title,kind:activityForm.kind,scheduled_at}).select().single();if(error){notify(`Jadwal gagal disimpan: ${error.message}`);return}activities=[{...row,id:row.id,date:row.scheduled_at.slice(0,10),time:row.scheduled_at.slice(11,16),done:false},...activities]}else activities=[{id:crypto.randomUUID(),...activityForm,done:false},...activities];modal='';notify('Kegiatan ditambahkan ke kalender.')}
	async function toggleActivity(item){const completed=!item.done;if(supabase&&user&&!String(item.id).startsWith('a')){const {error}=await supabase.from('activities').update({completed}).eq('id',item.id);if(error){notify(error.message);return}}activities=activities.map(x=>x.id===item.id?{...x,done:completed}:x)}
	async function startConsultation(){if(supabase&&user){const {data:row,error}=await supabase.from('consultations').insert({farmer_id:user.id,topic:consultTopic,description:consultText,status:'pending'}).select().single();if(error){notify(`Konsultasi gagal dibuat: ${error.message}`);return}consultations=[{id:row.id,name:'Menunggu penyuluh',specialty:'Tanaman Pangan',last:consultTopic,time:'Baru saja',online:false},...consultations]}else consultations=[{id:`c${Date.now()}`,name:'Siti Rahmawati, S.P.',specialty:'Tanaman Pangan',last:consultTopic,time:'Baru saja',online:true},...consultations];modal='';current='Chat Konsultasi';notify('Permintaan konsultasi dibuat.')}
	async function sendMessage(){if(!chatText.trim())return;const text=chatText.trim();if(supabase&&user&&consultations[0]?.id&&!String(consultations[0].id).startsWith('c')){const {error}=await supabase.from('messages').insert({consultation_id:consultations[0].id,sender_id:user.id,body:text});if(error){notify(error.message);return}}messages=[...messages,{from:'me',text,time:new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}];chatText=''}
	async function uploadChatImage(event){const file=event.currentTarget.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){notify('Pilih foto tanaman maksimal 5 MB.');return}if(supabase&&user){const path=`${user.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9.-]/g,'_')}`;const {error}=await supabase.storage.from('consultation-photos').upload(path,file,{contentType:file.type});if(error){notify(`Foto gagal diunggah: ${error.message}`);return}}messages=[...messages,{from:'me',text:`📷 Foto tanaman: ${file.name}`,time:new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}];notify('Foto tanaman berhasil dilampirkan.')}
	$: todayActivities=activities.filter(a=>a.date===new Date().toISOString().slice(0,10));
	$: filteredFields=fields.filter(f=>`${f.name} ${f.crop} ${f.location}`.toLowerCase().includes(searchText.toLowerCase()));
	$: pageTitle=selectedField?'Detail Lahan':current;
</script>

<svelte:head><title>{pageTitle} — Temu Penyuluh</title><meta name="description" content="Teman Digital Petani, dari Tanam hingga Panen." /></svelte:head>

{#if !loggedIn}
